diff --git a/web/report-button.ts b/web/report-button.ts
--- a/web/report-button.ts
+++ b/web/report-button.ts
@@ -1,6 +1,6 @@
 export function reportButton(): HTMLButtonElement {
   const button = document.createElement("button");
-  button.setAttribute("aria-label", "Downlaod report");
+  button.setAttribute("aria-label", "Download report");
   button.textContent = "↓";
   return button;
 }

diff --git a/web/report-button.test.ts b/web/report-button.test.ts
--- a/web/report-button.test.ts
+++ b/web/report-button.test.ts
@@ -2,5 +2,5 @@
 import { reportButton } from "./report-button";

 test("report button has an accessible name", () => {
-  expect(reportButton().getAttribute("aria-label")).toBe("Downlaod report");
+  expect(reportButton().getAttribute("aria-label")).toBe("Download report");
 });
